mapper.select:

   SELECT /* getAlimTemp */
          T.ALIM_SITU
        , T.TEMP_CODE
        , T.TEMP_TITL
        , CASE WHEN S.ENGL_YSNO = #{commYes} THEN COALESCE(NULLIF(T.ALIM_ENTL, ''), T.ALIM_TITL) ELSE T.ALIM_TITL END AS ALIM_TITL
        , CASE WHEN S.ENGL_YSNO = #{commYes} THEN COALESCE(NULLIF(T.TEMP_ENCT, ''), T.TEMP_CONT) ELSE T.TEMP_CONT END AS TEMP_CONT
        , T.USEE_YSNO
     FROM TB_ALTEMP T
LEFT JOIN TM_USSETX S
       ON S.USER_NUMB = #{userNumb}
    WHERE T.ALIM_SITU = #{alimSitu}
      AND T.TEMP_CODE = #{tempCode}
      AND T.USEE_YSNO = #{commYes}

mapper.insert:

    SELECT LAST_INSERT_ID()

/* setAlim */
INSERT INTO TB_ALIMXX (
            USER_NUMB
          , ALIM_NUMB
          , ALIM_SITU
          , TEMP_CODE
          , ALIM_TITL
          , ALIM_CONT
          , TAGT_TYPE
          , TAGT_NUMB
          , REPL_NUMB
          , CHAT_NUMB
          , READ_YSNO
          , SEND_DATE
          , DELT_YSNO
)
SELECT #{userNumb}
     , LAST_INSERT_ID(COALESCE(MAX(ALIM.ALIM_NUMB), 0) + 1)
     , #{alimSitu}
     , #{tempCode}
     , #{alimTitl}
     , #{alimCont}
     , #{tagtType,jdbcType=VARCHAR}
     , #{tagtNumb,jdbcType=BIGINT}
     , #{replNumb,jdbcType=BIGINT}
     , #{chatNumb,jdbcType=BIGINT}
     , #{readYsno}
     , CURRENT_TIMESTAMP
     , #{deltYsno}
  FROM TB_ALIMXX ALIM
 WHERE ALIM.USER_NUMB = #{userNumb}

mapper.select:

SELECT /* dupSameAlimInHour */
       COUNT(*)
  FROM TB_ALIMXX
 WHERE USER_NUMB = #{userNumb}
   AND ALIM_SITU = #{alimSitu}
   AND TEMP_CODE = #{tempCode}
   AND COALESCE(ALIM_TITL, ' ') = COALESCE(#{alimTitl}, ' ')
   AND COALESCE(ALIM_CONT, ' ') = COALESCE(#{alimCont}, ' ')
   AND COALESCE(TAGT_TYPE, ' ') = COALESCE(#{tagtType}, ' ')
   AND COALESCE(TAGT_NUMB, -1) = COALESCE(#{tagtNumb}, -1)
   AND COALESCE(REPL_NUMB, -1) = COALESCE(#{replNumb}, -1)
   AND COALESCE(DELT_YSNO, #{commNo}) = #{commNo}
   AND SEND_DATE >= DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 1 HOUR)

mapper.update:


UPDATE /* uptAlimRead */
       TB_ALIMXX
   SET READ_YSNO = #{commYes}
     , READ_DATE = CURRENT_TIMESTAMP
 WHERE USER_NUMB = #{userNumb}
   AND ALIM_NUMB = #{alimNumb}
   AND COALESCE(DELT_YSNO, #{commNo}) = #{commNo}
   AND COALESCE(READ_YSNO, #{commNo}) = #{commNo}



UPDATE /* delAllAlim */
       TB_ALIMXX
   SET DELT_YSNO = #{commYes}
 WHERE USER_NUMB = #{userNumb}
   AND COALESCE(DELT_YSNO, #{commNo}) = #{commNo}

